package com.hbm.machine.generator.leviathan;
import api.hbm.redstoneoverradio.IRORValueProvider;
import com.hbm.api.computer.*;
import com.hbm.api.machine.*;
import com.hbm.energy.*;
import com.hbm.fluid.*;
import com.hbm.fluid.network.*;
import com.hbm.multiblock.DummyableBlock;
import java.math.*;
import java.util.*;
import java.util.function.Consumer;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
/** TileEntityTurbineBase+Chungus: consumesallavailablecoolablefluid, ephemeralper-tickHE, noflywheel/GUIinvented. */
public final class LeviathanEntity extends BlockEntity implements EnergyProvider,EnergyConductor,StandardFluidTransceiver,IFluidCopiable,MachineView,ComputerControl,IRORValueProvider, com.hbm.multiblock.MuffledMachine {
 public static Consumer<LeviathanEntity> CLIENT_TICK=machine->{},CLIENT_REMOVED=machine->{};
 public final FluidTank[] tanks={new FluidTank(HbmFluids.STEAM,LeviathanConfig.inputTankSize),new FluidTank(HbmFluids.SPENTSTEAM,LeviathanConfig.outputTankSize)};
 private BigInteger powerBuffer=BigInteger.ZERO;public boolean operational,muffled,tilted;public int turnTimer;public float rotor,lastRotor,fanAcceleration;public final float audioDesync=new Random().nextFloat()*.05F;
 private PowerNode node;private FluidPorts ports;private List<BlockPos> activeFluidPorts=List.of();private BlockPos activePowerPort;private CompoundTag inletSnapshot,outletSnapshot;private int inputConsumed,outputProduced;private BigInteger generated=BigInteger.ZERO;
 public LeviathanEntity(BlockPos pos,BlockState state){super(LeviathanContent.ENTITY.get(),pos,state);}
 @Override public boolean isValidBlockState(BlockState state){return super.isValidBlockState(state)&&DummyableBlock.isCore(state);}
 public static BlockPos[] fluidPortPositions(BlockPos core,BlockState state){var dir=DummyableBlock.facing(state);var side=dir.getClockWise();return new BlockPos[]{core.relative(dir,4).above(2),core.relative(side,2),core.relative(side.getOpposite(),2)};}
 public static BlockPos powerPortPosition(BlockPos core,BlockState state){return core.relative(DummyableBlock.facing(state).getOpposite(),10);}
 public static Direction fluidPortSide(BlockPos core,BlockState state,BlockPos port){var points=fluidPortPositions(core,state);var direction=DummyableBlock.facing(state);for(int i=0;i<points.length;i++)if(points[i].equals(port))return i==0?direction:i==1?direction.getClockWise():direction.getCounterClockWise();return null;}
 private boolean livePort(ServerLevel server,BlockPos pos){return server.hasChunkAt(pos)&&server.getBlockState(pos).is(getBlockState().getBlock())&&DummyableBlock.isPort(server.getBlockState(pos));}
 private void updatePorts(ServerLevel server){var power=powerPortPosition(worldPosition,getBlockState());if(!livePort(server,power))removePower();else if(node==null||node.isExpired()||!power.equals(activePowerPort)){removePower();activePowerPort=power;var side=DummyableBlock.facing(getBlockState()).getOpposite();node=new PowerNode(power).setConnections(new NodeConnection(power.relative(side),side));HbmEnergy.nodespace(server).createNode(node);}if(node!=null&&node.hasValidNet())node.addProvider(this);var loaded=new ArrayList<BlockPos>();for(var pos:fluidPortPositions(worldPosition,getBlockState()))if(livePort(server,pos))loaded.add(pos);if(!loaded.equals(activeFluidPorts)){removeFluids();activeFluidPorts=List.copyOf(loaded);if(!loaded.isEmpty()){var connections=new ArrayList<NodeConnection>();for(var pos:loaded){var side=fluidPortSide(worldPosition,getBlockState(),pos);connections.add(new NodeConnection(pos.relative(side),side));}ports=new FluidPorts(loaded.toArray(BlockPos[]::new),connections.toArray(NodeConnection[]::new));}}if(ports!=null)ports.update(server,this);}
 public static void tick(Level level,BlockPos pos,BlockState state,LeviathanEntity machine){if(level instanceof ServerLevel server)machine.serverTick(server);else machine.clientTick();}
 private void serverTick(ServerLevel server){updatePorts(server);powerBuffer=BigInteger.ZERO;inputConsumed=outputProduced=0;generated=BigInteger.ZERO;inletSnapshot=new CompoundTag();tanks[0].writeToNBT(inletSnapshot,"water");operational=false;boolean valid=false;var trait=tanks[0].getTankType().getTrait(FluidTraits.Coolable.class);if(trait!=null){double efficiency=trait.getEfficiency(FluidTraits.CoolingType.TURBINE)*LeviathanConfig.efficiency;if(efficiency>0){tanks[1].setTankType(trait.coolsTo());int inputOps=(int)(Math.min(Math.ceil(tanks[0].getFill()*1D),tanks[0].getFill())/trait.amountReq());int outputOps=(tanks[1].getMaxFill()-tanks[1].getFill())/trait.amountProduced();int operations=Math.min(inputOps,outputOps);if(operations>0){tanks[0].setFill(tanks[0].getFill()-operations*trait.amountReq());tanks[1].setFill(tanks[1].getFill()+operations*trait.amountProduced());powerBuffer=scaled(BigInteger.valueOf(operations).multiply(BigInteger.valueOf(trait.heatEnergy())),efficiency);}inputConsumed=operations*trait.amountReq();outputProduced=operations*trait.amountProduced();generated=scaled(BigInteger.valueOf(operations).multiply(BigInteger.valueOf(trait.heatEnergy())),efficiency);valid=true;operational=operations>0;}}
  turnTimer--;if(operational)turnTimer=25;outletSnapshot=new CompoundTag();tanks[1].writeToNBT(outletSnapshot,"steam");if(!valid)tanks[1].setTankType(HbmFluids.NONE);setChanged();var packet=getUpdatePacket();try(var dispatchScope=com.hbm.network.dispatch.PacketDispatch.beginGroup(server.getServer(),packet)){for(var player:server.players())if(player.distanceToSqr(worldPosition.getX(),worldPosition.getY(),worldPosition.getZ())<22500)player.connection.send(packet);dispatchScope.commit();}
 }
 private static BigInteger scaled(BigInteger value,double factor){double original=value.doubleValue()*factor;if(Double.isNaN(original))return BigInteger.ZERO;if(!Double.isFinite(factor))return BigInteger.valueOf((long)original);if(value.bitLength()<63&&Double.isFinite(original)&&original>=-0x1.0p63&&original<0x1.0p63)return BigInteger.valueOf((long)original);return new BigDecimal(value).multiply(BigDecimal.valueOf(factor)).toBigInteger();}
 private void clientTick(){lastRotor=rotor;rotor+=fanAcceleration;if(rotor>=360){rotor-=360;lastRotor-=360;}if(turnTimer>0)fanAcceleration=Math.max(0,Math.min(25,fanAcceleration+.075F+audioDesync));else fanAcceleration=Math.max(0,Math.min(25,fanAcceleration-.1F));CLIENT_TICK.accept(this);}
 public void onLeverPull(){var input=tanks[0].getTankType();if(input==HbmFluids.STEAM){tanks[0].setTankType(HbmFluids.HOTSTEAM);tanks[1].setTankType(HbmFluids.STEAM);}else if(input==HbmFluids.HOTSTEAM){tanks[0].setTankType(HbmFluids.SUPERHOTSTEAM);tanks[1].setTankType(HbmFluids.HOTSTEAM);}else if(input==HbmFluids.SUPERHOTSTEAM){tanks[0].setTankType(HbmFluids.ULTRAHOTSTEAM);tanks[1].setTankType(HbmFluids.SUPERHOTSTEAM);}else{tanks[0].setTankType(HbmFluids.STEAM);tanks[1].setTankType(HbmFluids.SPENTSTEAM);}setChanged();}
 @Override public boolean canConnect(Direction side){return side!=null&&side.getAxis().isHorizontal();}@Override public boolean isLoaded(){return !isRemoved()&&level!=null&&level.hasChunkAt(worldPosition);}@Override public PowerNode energyNode(){return node;}
 private static long legacy(BigInteger value){return value.max(BigInteger.valueOf(Long.MIN_VALUE)).min(BigInteger.valueOf(Long.MAX_VALUE)).longValue();}@Override public long getPower(){return legacy(powerBuffer);}@Override public long getMaxPower(){return getPower();}@Override public BigInteger getPowerExact(){return powerBuffer;}@Override public BigInteger getMaxPowerExact(){return powerBuffer;}@Override public BigInteger getProviderSpeedExact(){return powerBuffer;}@Override public void setPower(long power){setPowerExact(BigInteger.valueOf(power));}@Override public void setPowerExact(BigInteger power){powerBuffer=power;setChanged();}@Override public void usePower(long amount){usePowerExact(BigInteger.valueOf(amount));}@Override public void usePowerExact(BigInteger amount){if(amount.signum()<0||amount.compareTo(powerBuffer)>0)throw new IllegalArgumentException("Unavailable HE requested");powerBuffer=powerBuffer.subtract(amount);setChanged();}
 @Override public FluidTank[] getAllTanks(){return tanks;}@Override public FluidTank[] getReceivingTanks(){return new FluidTank[]{tanks[0]};}@Override public FluidTank[] getSendingTanks(){return new FluidTank[]{tanks[1]};}@Override public FluidTank getTankToPaste(){return null;}@Override public long transferFluid(HbmFluidType type,int pressure,long amount){long left=StandardFluidTransceiver.super.transferFluid(type,pressure,amount);if(left!=amount)setChanged();return left;}@Override public void useUpFluid(HbmFluidType type,int pressure,long amount){StandardFluidTransceiver.super.useUpFluid(type,pressure,amount);setChanged();}
 @Override public long energyStored(){return getPower();}@Override public long energyCapacity(){return getMaxPower();}@Override public BigInteger energyStoredExact(){return powerBuffer;}@Override public BigInteger energyCapacityExact(){return powerBuffer;}@Override public List<TankView> tanks(){return List.of(new TankView(tanks[0].getTankType(),tanks[0].getFill(),tanks[0].getMaxFill()),new TankView(tanks[1].getTankType(),tanks[1].getFill(),tanks[1].getMaxFill()));}public int inputConsumed(){return inputConsumed;}public int outputProduced(){return outputProduced;}public BigInteger generatedPower(){return generated;}
 public int steamType(){var type=tanks[0].getTankType();return type==HbmFluids.HOTSTEAM?1:type==HbmFluids.SUPERHOTSTEAM?2:type==HbmFluids.ULTRAHOTSTEAM?3:0;}
 private Object computerPower(){return powerBuffer.bitLength()<64?powerBuffer.longValue():powerBuffer.toString();}@Override public String computerType(){return "ntm_turbine";}@Override public String[] computerMethods(){return new String[]{"getFluid","getType","setType","getPower","getInfo"};}@Override public Object[] callComputer(String method,ComputerArguments args){return switch(method){case "getFluid"->new Object[]{tanks[0].getFill(),tanks[0].getMaxFill(),tanks[1].getFill(),tanks[1].getMaxFill()};case "getType"->new Object[]{steamType()};case "setType"->{int type=args.checkInteger(0);tanks[0].setTankType(type==1?HbmFluids.HOTSTEAM:type==2?HbmFluids.SUPERHOTSTEAM:type==3?HbmFluids.ULTRAHOTSTEAM:HbmFluids.STEAM);setChanged();yield new Object[]{};}case "getPower"->new Object[]{computerPower()};case "getInfo"->new Object[]{tanks[0].getFill(),tanks[0].getMaxFill(),tanks[1].getFill(),tanks[1].getMaxFill(),steamType(),computerPower()};default->throw new ComputerException("No such method: "+method);};}
 @Override public String[] getFunctionInfo(){return new String[]{PREFIX_VALUE+"output"};}@Override public String provideRORValue(String name){return (PREFIX_VALUE+"output").equals(name)?""+powerBuffer.intValue():null;}
 private void removePower(){if(node!=null&&!node.isExpired()&&level instanceof ServerLevel server)HbmEnergy.nodespace(server).destroyNode(node);node=null;activePowerPort=null;}private void removeFluids(){if(ports!=null&&level instanceof ServerLevel server)ports.remove(server);ports=null;activeFluidPorts=List.of();}private void disconnect(){removePower();removeFluids();if(level!=null&&level.isClientSide)CLIENT_REMOVED.accept(this);}@Override public void setRemoved(){disconnect();super.setRemoved();}@Override public void onChunkUnloaded(){disconnect();super.onChunkUnloaded();}
 private static BigInteger readHE(CompoundTag tag){return tag.contains("power",Tag.TAG_STRING)?new BigInteger(tag.getString("power")):BigInteger.valueOf(tag.getLong("power"));}@Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);tanks[0].writeToNBT(tag,"water");tanks[1].writeToNBT(tag,"steam");tag.putString("power",powerBuffer.toString());tag.putBoolean("muffled",muffled);tag.putBoolean("tilted",tilted);}@Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);tanks[0].readFromNBT(tag,"water");tanks[1].readFromNBT(tag,"steam");powerBuffer=readHE(tag);muffled=tag.getBoolean("muffled");tilted=tag.getBoolean("tilted");}
 @Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=new CompoundTag();if(inletSnapshot!=null)tag.merge(inletSnapshot);else tanks[0].writeToNBT(tag,"water");if(outletSnapshot!=null)tag.merge(outletSnapshot);else tanks[1].writeToNBT(tag,"steam");tag.putString("power",powerBuffer.toString());tag.putInt("turnTimer",turnTimer);tag.putBoolean("muffled",muffled);tag.putBoolean("tilted",tilted);return tag;}@Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){tanks[0].readFromNBT(tag,"water");tanks[1].readFromNBT(tag,"steam");powerBuffer=readHE(tag);turnTimer=tag.getInt("turnTimer");muffled=tag.getBoolean("muffled");tilted=tag.getBoolean("tilted");}@Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public void onDataPacket(net.minecraft.network.Connection connection,ClientboundBlockEntityDataPacket packet,HolderLookup.Provider lookup){handleUpdateTag(packet.getTag(),lookup);}

 @Override public boolean isMuffled(){return muffled;}
 @Override public void setMuffled(boolean value){muffled=value;}
}
